            if node not in index:
                strongconnect(node)

        return sccs

    # Initialize the graph
    graph = [[] for _ in range(n + 1)]

    # Create the graph based on the problem constraints
    for i in range(1, n + 1):
        graph[i].append((i % n) + 1)

    # Find all SCCs using Tarjan's algorithm
    sccs = tarjan_scc()

    # Count the number of valid configurations
    valid_configurations = 1

    for scc in sccs:
        if 1 in scc:
            # If the SCC contains house 1, it must include all houses from 1 to k
            if max(scc) > k:
